/* NEXZO Settings Controller v4 — functional controls, account actions and diagnostics. */
(function(){
'use strict';if(document.body?.dataset.page!=='settings'||window.__NEXZO_SETTINGS_V4__)return;window.__NEXZO_SETTINGS_V4__=true;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panels=['general','preferences','notifications','privacy','account','about'];let active='general';
const mgr=()=>window.NEXZOSettings, s=()=>mgr()?.get()||{};const toast=(m,t='info')=>window.NEXZOShell?.toast?.(m,t);
const opts=(key,values,labels={})=>`<div class="settings-v3-segmented">${values.map(v=>`<button type="button" class="${s()[key]===v?'active':''}" data-set="${key}" data-value="${v}">${labels[v]||v}</button>`).join('')}</div>`;
const row=(icon,title,desc,control)=>`<div class="settings-v3-setting-row"><div class="settings-v3-setting-info"><span class="settings-v3-setting-icon">${icon}</span><div class="settings-v3-setting-copy"><b>${title}</b><small>${desc}</small></div></div>${control}</div>`;
const toggle=(key,title,desc,icon)=>row(icon,title,desc,`<button type="button" class="settings-v4-toggle" data-toggle="${key}" role="switch" aria-checked="${!!s()[key]}" aria-pressed="${!!s()[key]}">${s()[key]?'ON':'OFF'}</button>`);
const select=(key,title,desc,icon,values)=>row(icon,title,desc,`<select data-select="${key}">${values.map(v=>`<option ${s()[key]===v?'selected':''}>${v}</option>`).join('')}</select>`);
const card=(title,desc,body,accent='purple')=>`<article class="settings-v3-card" data-accent-card="${accent}"><div class="settings-v3-card-title"><span class="settings-v3-title-icon">◉</span><div><h2>${title}</h2><p>${desc}</p></div></div>${body}</article>`;
function general(){const a=window.NEXZOSettings?.accents||{};return card('Appearance','Applied instantly across every NEXZO page.',row('◐','Theme','Dark, light or your operating-system theme.',opts('mode',['dark','light','system'],{dark:'Dark',light:'Light',system:'System'}))+row('🎨','Accent','Buttons, progress bars, active states and highlights.',`<div class="settings-v3-color-grid">${Object.entries(a).map(([n,c])=>`<button type="button" class="${s().accent===n?'active':''}" data-set="accent" data-value="${n}" style="--swatch:${c}"><i></i><span>${n[0].toUpperCase()+n.slice(1)}</span></button>`).join('')}</div>`)+row('Aa','Font size','Readable content size without scaling the browser.',opts('font',['small','medium','large','xl'],{small:'Small',medium:'Medium',large:'Large',xl:'XL'}))+row('▦','Interface density','Controls card padding and page spacing.',opts('density',['compact','comfortable','spacious'],{compact:'Compact',comfortable:'Comfortable',spacious:'Spacious'}))+row('✦','Motion','Reduced removes non-essential motion; Off removes animation backgrounds.',opts('motion',['smooth','reduced','off'],{smooth:'Smooth',reduced:'Reduced',off:'Off'}))+row('☰','Sidebar','Choose expanded, compact or icons-only navigation.',opts('sidebar',['expanded','compact','icons'],{expanded:'Expanded',compact:'Compact',icons:'Icons only'})))}
function preferences(){return card('Study Preferences','Defaults used by Planner, Dashboard and reminders.',select('defaultStudyTime','Default study time','New study plans use this target.','⏱',['30 Min','1 Hour','2 Hours','3 Hours','4 Hours'])+select('weekStart','Week starts on','Used by weekly charts and reports.','📅',['Monday','Sunday'])+select('language','Language','Stored as your interface and AI language preference.','🌐',['English','Hindi','Hinglish'])+select('timeZone','Timezone','Used for local reminders and daily resets.','⌚',['Asia/Kolkata','UTC','Asia/Dubai','Europe/London','America/New_York'])+toggle('focusMode','Focus mode','Reduces non-essential interface distractions.','🎯')+toggle('autoSync','Automatic cloud sync','Local changes save first, then Firestore syncs when available.','☁️'))}
function notifications(){return card('Notifications','No permission prompt occurs automatically.',toggle('notifyTasks','Task reminders','Upcoming and overdue Planner tasks.','📅')+toggle('notifyCommunity','Community activity','Replies, group messages and relevant activity.','👥')+toggle('notifyStreak','Streak reminders','Warn before the study streak is at risk.','🔥')+toggle('sound','Notification sound','Sound for completed actions and alerts.','🔊')+select('emailDigest','Email digest','Preference only; delivery requires a configured backend email service.','✉️',['Off','Daily','Weekly'])+row('🔔','Browser & push notifications','Permission is requested only when you click Enable. Remote push also requires the Firebase Web Push key.',`<button class="btn" id="requestPermission">Enable notifications</button><small class="settings-v4-note" id="permissionState">${'Notification' in window?Notification.permission:'Unsupported'}</small>`))}
function privacy(){return card('Privacy & Personalization','Honest local controls; no unconfigured analytics claims.',select('profileVisibility','Profile visibility','Public, friends-only or private.','👤',['Public','Friends only','Private'])+toggle('activityStatus','Activity status','Allow social features to expose your active state.','⚡')+toggle('diagnostics','Diagnostic logs','Store optional local errors for troubleshooting.','🧪')+toggle('analytics','Anonymous analytics','Stores preference only until analytics is actually configured.','📈')+toggle('personalization','AI personalization','When OFF, stored tasks, weak topics and history are excluded from AI context.','🤖')+row('🍪','Consent preferences','Review optional analytics and personalization choices.',`<button class="btn" id="manageConsent">Manage consent</button>`)+row('🧹','Clear diagnostic data','Only logs, cached errors and temporary diagnostics are removed.',`<button class="btn" id="clearDiagnostics">Clear diagnostic data</button>`))}
async function authInfo(){try{const {auth}=await window.NEXZOFirebase.getAuthContext();return auth.currentUser}catch{return null}}
function account(){return card('Account','Manage your sign-in, security and personal data.',`<div id="accountDynamic">Loading account…</div>`,'gold')}
function about(){return card('About NEXZO','Your personalized learning and productivity workspace.',row('◇','Version','Current NEXZO web experience.','<b>4.0.0</b>')+row('✦','Study Assistant','Get study help, explanations and guided learning.','<a class="btn" href="ai-assistant.html">Open Study Assistant</a>')+row('🔒','Privacy & Terms','Review how NEXZO handles your account and data.','<span class="settings-v4-links"><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a></span>'))}
const renderers={general,preferences,notifications,privacy,account,about};
function render(name=active){active=panels.includes(name)?name:'general';document.querySelectorAll('#settingsV3Tabs [data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===active));$('settingsV3Content').innerHTML=renderers[active]();bind();if(active==='account')renderAccount();updatePreview()}
function save(k,v){mgr().set({[k]:v});render(active);if(k==='emailDigest'&&v!=='Off')toast('Preference saved — email delivery requires backend configuration.','info');else toast('Setting saved.','success')}
function confirmModal(title,text,onYes){const m=document.createElement('div');m.className='settings-v4-modal';m.innerHTML=`<div><h2>${title}</h2><p>${text}</p><div class="settings-v4-modal-actions"><button class="btn" data-no>Cancel</button><button class="btn danger" data-yes>Continue</button></div></div>`;document.body.appendChild(m);m.querySelector('[data-no]').onclick=()=>m.remove();m.querySelector('[data-yes]').onclick=async()=>{m.remove();await onYes()}}
function bind(){document.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>save(b.dataset.set,b.dataset.value));document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>save(b.dataset.toggle,!s()[b.dataset.toggle]));document.querySelectorAll('[data-select]').forEach(e=>e.onchange=()=>save(e.dataset.select,e.value));$('requestPermission')?.addEventListener('click',async()=>{const result=await window.NEXZOConsent?.enablePush?.();const status=result?.status||('Notification'in window?Notification.permission:'unsupported');$('permissionState').textContent=status==='ready'?'Push ready':status==='permission-granted'?'Allowed · remote push setup pending':status;toast(status==='ready'?'Notifications are ready on this device.':status==='permission-granted'?'Browser notifications allowed. Add the Firebase Web Push key to enable remote push.':`Notification status: ${status}`,status==='ready'?'success':'info')});$('manageConsent')?.addEventListener('click',()=>window.NEXZOConsent?.open?.());$('clearDiagnostics')?.addEventListener('click',()=>confirmModal('Clear diagnostic data?','Tasks, XP, profile, posts and AI history will not be deleted.',()=>{Object.keys(localStorage).filter(k=>/diagnostic|error|temp|runtime_log/i.test(k)).forEach(k=>localStorage.removeItem(k));toast('Diagnostic data cleared.','success')}))}
async function renderAccount(){const host=$('accountDynamic'),u=await authInfo();if(!u){host.innerHTML='<p>No Firebase user is signed in.</p>';return}const photo=u.photoURL?`<img src="${esc(u.photoURL)}" alt="Profile">`:`<span class="settings-v4-avatar">${esc((u.displayName||u.email||'N')[0])}</span>`;host.innerHTML=row('👤','Signed-in account','Your NEXZO account.',`<div class="settings-v4-account">${photo}<div><b>${esc(u.displayName||'No display name')}</b><small>${esc(u.email||'')}</small></div></div>`)+row('✉️','Email verification','Verify the email linked to your account.',`<button class="btn" id="verifyEmail" ${u.emailVerified?'disabled':''}>${u.emailVerified?'Verified':'Send verification'}</button>`)+row('🔐','Password reset','Send a password reset link to your email.',`<button class="btn" id="passwordReset">Send reset link</button>`)+row('⇧','Export my data','Download the NEXZO data available on this device.',`<button class="btn" id="exportData">Download JSON</button>`)+row('🗑','Delete account','Permanently delete your sign-in account. You may need to sign in again first.',`<button class="btn danger" id="deleteAccount">Delete account</button>`);bindAccount(u)}
async function connectionTest(){const out=$('componentStatus');out.innerHTML='<span>Testing…</span>';let auth='Disconnected',fire='Offline',ai='Offline',gemini='Unknown';try{const c=await window.NEXZOFirebase.getContext({auth:true,firestore:true});auth=c.auth.currentUser?'Connected':'Disconnected';if(c.auth.currentUser){try{const fs=c.firestoreTools,ref=fs.doc(c.db,'users',c.auth.currentUser.uid,'settings','connectionTest');await fs.setDoc(ref,{uid:c.auth.currentUser.uid,updatedAtMs:Date.now()},{merge:true});await fs.getDoc(ref);fire='Connected'}catch(e){fire=e.code==='permission-denied'?'Permission denied':'Offline'}}}catch{}try{const base=window.NEXZO_CONFIG?.API_BASE_URL||'http://127.0.0.1:5000/api';const r=await fetch(`${base.replace(/\/$/,'')}/health`,{cache:'no-store',signal:AbortSignal.timeout?.(5000)});const d=await r.json().catch(()=>({}));ai=r.ok?'Connected':'Offline';gemini=d.gemini?.status||d.geminiStatus||(d.geminiConfigured?'Configured':'Not reported')}catch{ai='Offline';gemini='Unavailable while backend is offline'}out.innerHTML=`<span>Firebase Auth <b>${auth}</b></span><span>Firestore <b>${fire}</b></span><span>Study Service <b>${ai}</b></span><span>Model Service <b>${esc(gemini)}</b></span>`}
function collectExport(){const pick=(re)=>Object.fromEntries(Object.keys(localStorage).filter(k=>re.test(k)).map(k=>[k,(()=>{try{return JSON.parse(localStorage.getItem(k))}catch{return localStorage.getItem(k)}})()]));return {exportedAt:new Date().toISOString(),user:window.NEXZOShell?.identity?.(),profile:pick(/profile/i),settings:s(),tasks:pick(/task|planner/i),rewards:window.NEXZOGamificationEngine?.summary?.()||pick(/gamification|reward|xp|coin/i),achievements:pick(/achievement/i),community:pick(/community|post|group/i),aiHistory:pick(/ai.*chat|chat.*history/i)}}
function bindAccount(u){$('verifyEmail').onclick=async()=>{try{const {tools}=await window.NEXZOFirebase.getAuthContext();await tools.sendEmailVerification(u);toast('Verification email sent.','success')}catch(e){toast(e.message,'error')}};$('passwordReset').onclick=async()=>{try{const {auth,tools}=await window.NEXZOFirebase.getAuthContext();await tools.sendPasswordResetEmail(auth,u.email);toast('Password reset email sent.','success')}catch(e){toast(e.message,'error')}};$('exportData').onclick=()=>window.NEXZOShell.download('nexzo-data-export.json',JSON.stringify(collectExport(),null,2),'application/json');$('deleteAccount').onclick=()=>confirmModal('Delete your account?', 'This removes the Firebase Auth account. Recent sign-in may be required. Full Admin-side cleanup is not claimed without a configured backend.',async()=>{try{const {tools}=await window.NEXZOFirebase.getAuthContext();await tools.deleteUser(u);toast('Firebase Auth account deleted.','success');location.href='login.html'}catch(e){toast(e.code==='auth/requires-recent-login'?'Recent authentication required. Sign in again, then retry.':e.message,'error')}})}
function clearTemporaryCache(){confirmModal('Clear temporary cache?','Your profile, Planner tasks, XP, Community data and settings will stay untouched.',async()=>{try{if('caches'in window){for(const key of await caches.keys())await caches.delete(key)}Object.keys(localStorage).filter(k=>/^(nexzo:)?(cache|temp|runtime_cache)/i.test(k)).forEach(k=>localStorage.removeItem(k));toast('Temporary cache cleared.','success')}catch(e){toast('Could not clear the temporary cache.','error')}})}
function resetUserSettings(){confirmModal('Reset settings?','Appearance and preference controls will return to their defaults. Your tasks, XP, profile and Community data will not be deleted.',async()=>{mgr().set({...mgr().defaults},{syncCloud:true});render('general');toast('Settings reset to defaults.','success')})}
async function syncUserSettings(){const b=$('settingsSync');try{if(b)b.disabled=true;const r=await mgr().sync();toast(r?.status==='connected'?'Settings synced.':'Settings saved locally; cloud sync is unavailable right now.',r?.status==='connected'?'success':'info')}catch{toast('Settings saved locally; cloud sync is unavailable right now.','info')}finally{if(b)b.disabled=false}}
function exportUserData(){window.NEXZOShell?.download?.('nexzo-data-export.json',JSON.stringify(collectExport(),null,2),'application/json');toast('Data export created.','success')}
async function logoutUser(){confirmModal('Log out of NEXZO?','Your saved data will remain associated with your account.',async()=>{try{const c=await window.NEXZOFirebase?.getAuthContext?.();if(c?.auth&&c?.tools?.signOut)await c.tools.signOut(c.auth);else if(window.NEXZOShell?.logout)await window.NEXZOShell.logout();location.href='login.html'}catch(e){toast(e?.message||'Could not log out.','error')}})}
function bindQuickActions(){$('settingsClearCache')?.addEventListener('click',clearTemporaryCache);$('settingsReset')?.addEventListener('click',resetUserSettings);$('settingsSync')?.addEventListener('click',syncUserSettings);$('settingsExport')?.addEventListener('click',exportUserData);$('settingsLogout')?.addEventListener('click',logoutUser)}
function updatePreview(){const v=s();$('settingsPreviewText')&&($('settingsPreviewText').textContent=`${v.mode} • ${v.motion} motion • ${v.density}`);$('settingsPreviewProgress')?.style.setProperty('width',v.density==='compact'?'45%':v.density==='spacious'?'90%':'70%')}
function init(){bindQuickActions();document.querySelectorAll('#settingsV3Tabs [data-panel]').forEach(b=>b.onclick=()=>render(b.dataset.panel));$('settingsGlobalSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();if(!q)return;const map={theme:'general',accent:'general',font:'general',notification:'notifications',privacy:'privacy',account:'account',password:'account',cloud:'account'};const hit=Object.entries(map).find(([k])=>q.includes(k));if(hit)render(hit[1])});window.openSettingsPanelV3=render;render()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
